export const FLAGS={green:{label:'VERDE',text:'Pista libera',color:'#77d88b'},yellow:{label:'BANDIERA GIALLA',text:'Pericolo: rallenta, niente sorpassi nella zona',color:'#f4cf52'},blue:{label:'BANDIERA BLU',text:'Un pilota sta per doppiarti: lascia spazio',color:'#67a9ff'},red:{label:'BANDIERA ROSSA',text:'Gara sospesa: rallenta fino a fermarti',color:'#ff6469'},vsc:{label:'VSC · NEUTRALIZZAZIONE',text:'Massimo 90 km/h · niente sorpassi',color:'#f4cf52'},chequered:{label:'BANDIERA A SCACCHI',text:'Gara conclusa',color:'#eeeeed'}};
export class RaceControl{
 constructor(){this.flag='green';this.remaining=4;this.zone=null;this.incidents=[];this.violations=0;this.cooldown=0;this.lastOrder=[];this.elapsed=0;this.sequence=0;}
 incident(progress,severity=1,now=this.elapsed){this.incidents=this.incidents.filter(i=>now-i.time<18);this.incidents.push({time:now,progress,severity});this.zone=progress;this.sequence++;if(severity>=3||this.incidents.length>=3){this.flag='red';this.remaining=7;}else if(severity>=2||this.incidents.length>=2){this.flag='vsc';this.remaining=18;}else{this.flag='yellow';this.remaining=13;}return this.flag;}
 set(flag,seconds=12,zone=null){if(!FLAGS[flag])return;this.flag=flag;this.remaining=seconds;this.zone=zone;this.sequence++;}
 applies(player,track){if(this.flag==='vsc'||this.flag==='red')return true;if(this.flag!=='yellow')return false;const d=((this.zone-player.progress+track.length*.5)%track.length+track.length)%track.length-track.length*.5;return d>-55&&d<210;}
 tick(dt,race){this.elapsed+=dt;this.cooldown=Math.max(0,this.cooldown-dt);if(this.remaining>0){this.remaining-=dt;if(this.remaining<=0&&this.flag!=='chequered'){const red=this.flag==='red';this.set('green',4);return{restart:red};}}if(race?.state==='finished'&&this.flag!=='chequered')this.set('chequered',1e9);return null;}
 info(race){let flag=this.flag;if(flag==='yellow'&&race&&!this.applies(race.player,race.track))flag='green';if(flag==='green'&&race?.riders?.some(r=>!r.isPlayer&&r.progress-race.player.progress>race.track.length-18&&r.progress-race.player.progress<race.track.length+25))flag='blue';return{flag,...FLAGS[flag],remaining:Math.max(0,this.remaining),zone:this.zone};}
 speedPenalty(race,dt){if(this.flag!=='vsc'||race.player.speed<90/3.6+2||this.cooldown>0)return 0;this.violations+=dt;if(this.violations<3)return 0;this.violations=0;this.cooldown=5;return 3;}
}
